Let $C$ be the set of continuous functions $f : \mathbb{R} \to \mathbb{R}$. Let $T : C \to C$ satisfty the following two properties:
\begin{enumerate}
\item Linearity: $T(af + bg) = aT(f) + bT(g)$ for all $a, b \in \mathbb{R}$ and all $f, g \in C$.
\item Locality: If $f \in C$ and $g \in C$ are identical on some interval $I$, then $T(f)$ and $T(g)$ are also identical on $I$.
\end{enumerate}
Prove that there exists some function $f \in C$ such that $T(g(x)) = f(x)g(x)$ for all $g \in C$.

Define $S_0$ to be $1$. For $n \geq 1$, let $S_n$ be the number of $n \times n$ matrices whose elements are nonnegative integers with the property that $a_{ij}=a_{ji}$, ($i,j=1,2,\dots,n$) and where $\sum_{i=1}^n a_{ij}=1$, ($j=1,2,\dots,n$). Prove
\begin{enumerate}
\item[(a)] $S_{n+1}=S_n+nS_{n-1}$
\item[(b)] $\sum_{n=0}^\infty S_n\frac{x^n}{n!} = \exp(x+x^2/2)$, where $\exp(x)=e^x$.
\end{enumerate}

Let $0 \leq p \leq 1$ and $0 \leq r \leq 1$ and consider the identities
\begin{enumerate}
\item[(a)] $(px+(1-p)y)^2=Ax^2+Bxy+Cy^2$,
\item[(b)] $(px+(1-p)y)(rx+(1-r)y)=\alpha x^2+\beta xy+\gamma y^2$.
\end{enumerate}
Show that (with respect to $p$ and $r$)
\begin{enumerate}
\item[(a)] $\max\{A,B,C\} \geq 4/9$,
\item[(b)] $\max\{\alpha,\beta,\gamma\} \geq 4/9$.
\end{enumerate}

Let $S$ be a finite set. Prove that there exists a list of subsets of $S$ such that
\begin{enumerate}
\item The first element of the list is the empty set,
\item Each subset of $S$ occurs exactly once in the list, and
\item Each successive element in the list is formed by adding or removing one element from the previous subset in the list.
\end{enumerate}

A binary operation (represented by multiplication) on $S$ has the property that $(ab)(cd) = ad$ for all $a, b, c, d$. Show that:
\begin{itemize}
\item[(1)] if $ab = c$, then $cc = c$;
\item[(2)] if $ab = c$, then $ad = cd$ for all $d$.
\end{itemize}
Find a set $S$, and such a binary operation, which also satisfies:
\begin{itemize}
\item[(A)] $a a = a$ for all $a$;
\item[(B)] $ab = a \neq b$ for some $a, b$;
\item[(C)] $ab \neq a$ for some $a, b$.
\end{itemize}

\begin{enumerate}
\item[(a)] Prove that there exist integers $a,b,c$, not all zero and each of absolute value less than one million, such that $|a+b\sqrt{2}+c\sqrt{3}|<10^{-11}$.
\item[(b)] Let $a,b,c$ be integers, not all zero and each of absolute value less than one million. Prove that $|a+b\sqrt{2}+c\sqrt{3}|>10^{-21}$.
\end{enumerate}

Let $\alpha=1+a_1x+a_2x^2+\cdots$ be a formal power series with coefficients in the field of two elements. Let
\[
a_n =
\begin{cases}
1 & \parbox{2in}{if every block of zeros in the binary expansion of $n$ has an even number of zeros in the block} \\[.3in]
0 & \text{otherwise.}
\end{cases}
\]
(For example, $a_{36}=1$ because $36=100100_2$ and $a_{20}=0$ because $20=10100_2.$) Prove that $\alpha^3+x\alpha+1=0.$

Suppose $f$ and $g$ are non-constant, differentiable, real-valued functions defined on $(-\infty,\infty)$. Furthermore, suppose that for each pair of real numbers $x$ and $y$,
\begin{align*}
f(x+y)&=f(x)f(y)-g(x)g(y), \\
g(x+y)&=f(x)g(y)+g(x)f(y).
\end{align*}
If $f'(0)=0$, prove that $(f(x))^2+(g(x))^2=1$ for all $x$.

Prove that $f(n) = 1-n$ is the only integer-valued function defined on the integers that satisfies the following conditions.
\begin{itemize}
\item[(i)] $f(f(n)) = n$, for all integers $n$;
\item[(ii)] $f(f(n+2)+2) = n$ for all integers $n$;
\item[(iii)] $f(0) = 1$.
\end{itemize}

Let $M$ be a set of real $n \times n$ matrices such that
\begin{itemize}
\item[(i)] $I \in M$, where $I$ is the $n \times n$ identity matrix;
\item[(ii)] if $A \in M$ and $B \in M$, then either $AB \in M$ or $-AB \in M$, but not both;
\item[(iii)] if $A \in M$ and $B \in M$, then either $AB = BA$ or $AB = -BA$;
\item[(iv)] if $A \in M$ and $A \neq I$, there is at least one $B \in M$ such that $AB = -BA$.
\end{itemize}
Prove that $M$ contains at most $n^2$ matrices.

Define a sequence $\{u_n\}_{n=0}^\infty$ by $u_0=u_1=u_2=1$, and thereafter by the condition that $\det \begin{pmatrix}
u_n & u_{n+1} \\
u_{n+2} & u_{n+3}
\end{pmatrix} = n!$ for all $n \geq 0$. Show that $u_n$ is an integer for all $n$. (By convention, $0!=1$.)

Let $f: (1, \infty) \to \mathbb{R}$ be a differentiable function such that
\[
 f'(x) = \frac{x^2 - f(x)^2}{x^2 (f(x)^2 + 1)}
\qquad \mbox{for all $x>1$.}
\]
Prove that $\lim_{x \to \infty} f(x) = \infty$.

Let $F:\mathbb{R}^2 \to \mathbb{R}$ and $g:\mathbb{R} \to \mathbb{R}$ be twice continuously differentiable functions with the following properties:
\begin{itemize}
\item $F(u,u)=0$ for every $u \in \mathbb{R}$;
\item for every $x \in \mathbb{R}$, $g(x)>0$ and $x^2g(x) \leq 1$;
\item for every $(u,v) \in \mathbb{R}^2$, the vector $\nabla F(u,v)$ is either $\mathbf{0}$ or parallel to the vector $\langle g(u),-g(v) \rangle$.
\end{itemize}
Prove that there exists a constant $C$ such that for every $n \geq 2$ and any $x_1,\dots,x_{n+1} \in \mathbb{R}$, we have $\min_{i \neq j} |F(x_i,x_j)| \leq \frac{C}{n}$.

Let $S$ be a class of functions from $[0, \infty)$ to $[0, \infty)$ that satisfies:
\begin{itemize}
\item[(i)]
The functions $f_1(x) = e^x - 1$ and $f_2(x) = \ln(x+1)$ are in $S$;
\item[(ii)]
If $f(x)$ and $g(x)$ are in $S$, the functions $f(x) + g(x)$ and $f(g(x))$ are in $S$;
\item[(iii)]
If $f(x)$ and $g(x)$ are in $S$ and $f(x) \geq g(x)$ for all $x \geq 0$, then the function
$f(x) - g(x)$ is in $S$.
\end{itemize}
Prove that if $f(x)$ and $g(x)$ are in $S$, then the function $f(x) g(x)$ is also in $S$.
